insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-cbb-perfect-ph-probiotic-gummies', 'CBB Perfect PH Probiotic Gummies', 'CBB (Curvy Body Bears)', 'supplement', 'physical', 'Pineapple-flavored gummies sold as "vaginal probiotics". The bottle says they help maintain a healthy vaginal pH, support yeast balance and keep odor away, and lists odor control, healthy pH, yeast balance and vaginal flow. The only probiotic named is Bacillus coagulans, a spore-forming gut bacterium, not one of the Lactobacillus species that dominate a healthy vagina. The Amazon title also lists vitamin C. 60 gummies, which the listing calls a 30-day supply. Vegan, gluten-free, soy-free and non-GMO per the listing.', '$17.99 on Amazon (60 gummies)', 'https://m.media-amazon.com/images/I/41qCKV-R2gL._AC_SL500_.jpg', 'https://www.amazon.com/dp/B0F7QXCGR5', '["cbb","curvy body bears","vaginal health","probiotic","gummies","ph balance","bacillus coagulans","vegan","supplement"]'::jsonb, '["vaginal-health","supplement"]'::jsonb, '["Amazon"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Sold as a dietary supplement. The listing says its statements have not been evaluated by the FDA and that it is not intended to diagnose, treat, cure, or prevent any disease.","materials":"60 gummies (30-day supply per the listing). Manufacturer listed as Curvy Body Bears; country of manufacture not stated. Labeled vegan, gluten-free, halal and allergen-free on the bottle.","recalls":"No recalls found.","sideEffects":"No warnings or directions were shown on the Amazon listing. Check the bottle before use, and ask a clinician first if you are pregnant, breastfeeding or have a medical condition.","opinionAlerts":"Labeled \"vaginal probiotics\", but the only probiotic named is Bacillus coagulans, with no strain code or CFU, so it can''t be matched to any study. Vitamin C is in the title but not the ingredient list. No study of this product was found."}'::jsonb, 'CBB says Perfect PH gummies help maintain a healthy vaginal pH, support yeast balance and keep odor away. No study of this product was found, and the listing doesn''t cite one.

The only probiotic named is Bacillus coagulans, a spore-forming bacterium mostly studied for the gut. A healthy vagina is usually dominated by Lactobacillus species, and this product contains none. The label gives no strain code and no CFU count, so there is no way to match it to published research. NIH notes that effects depend on the specific strain, so research on one kind of probiotic doesn''t carry over to another.

The listing also names vitamin C in its title but not in the ingredient list, so it isn''t clear how much, if any, each gummy contains.', 'Rated 4.5 out of 5 from 139 ratings on Amazon (81% five-star, 7% four-star, 4% three-star, 3% two-star, 5% one-star). Most of the reviews shown praise the pineapple taste and the gummy format; a few say it helps them feel balanced. One reviewer whose spouse took them for a while noticed no improvements or side effects, and said the gummies stuck together over time.', 'No study of this product or its strain was found. The label names Bacillus coagulans without a strain code or CFU, so its effect is unknown.', 'independent', 'ayna summary of NIH (NCCIH) information on probiotics. Not a direct clinician quote; no study of this product or its strain was found.', 'curated', false, false, 4.5, true, '{"userRatingSourceUrl":"https://www.amazon.com/dp/B0F7QXCGR5","ingredients":"Per the Amazon listing: Natural Pineapple Flavor, Orange juice concentrate, Bacillus Coagulans. The bottle''s key ingredients are Bacillus coagulans (probiotic) and pineapple fruit powder. The listing title and description also mention vitamin C, but it isn''t in the ingredient text. No strain code, CFU count or Supplement Facts panel was shown.","doctorOpinionShort":"Sold as a vaginal probiotic, but its only named probiotic is Bacillus coagulans, a gut bacterium, with no strain code or CFU, so it can''t be matched to any research. No study of this product was found.","doctorOpinionCitations":[{"url":"https://www.amazon.com/dp/B0F7QXCGR5","label":"Amazon: CBB Perfect PH Probiotic Gummies, ingredients and claims"},{"url":"https://www.nccih.nih.gov/health/probiotics-usefulness-and-safety","label":"NIH (NCCIH): Probiotics, usefulness and safety"}],"whoItsFor":["Adults who want a flavored gummy instead of a capsule and accept that the evidence is thin","Not a treatment for BV, a yeast infection or a UTI: see a clinician if you have symptoms such as odor, itching or unusual discharge"],"warnings":["A probiotic doesn''t treat an active infection. See a clinician for symptoms of BV, a yeast infection or a UTI.","Pregnant, breastfeeding, or managing a medical condition: check with a clinician before use.","The listing shows no dose directions; follow the bottle."],"ingredientScience":[{"name":"Why the strain matters","text":"NIH notes that different probiotics can have different effects, and the most common probiotics are Lactobacillus and Bifidobacterium. This product''s only named probiotic is Bacillus coagulans, with no strain code, so no study can be matched to it.","citations":[{"url":"https://www.nccih.nih.gov/health/probiotics-usefulness-and-safety","label":"NIH (NCCIH): Probiotics, usefulness and safety"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[{"url":"https://www.nccih.nih.gov/health/probiotics-usefulness-and-safety","text":"NIH (NCCIH): Probiotics","summary":"Effects depend on the specific strain."}]},"community":{"links":[{"platform":"website","url":"https://www.amazon.com/dp/B0F7QXCGR5","text":"Amazon: CBB Perfect PH Probiotic Gummies reviews","summary":"4.5 out of 5 from 139 ratings on Amazon."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-cbb-13-in-1-womens-gummies', 'CBB Women''s 13 in 1 Supplement Gummies', 'CBB (Curvy Body Bears)', 'supplement', 'physical', 'Berry-flavored gummies with four vitamins (A, C, E, and B6) and a 450 mg blend of nine herbs: maca, Asian ginseng, anise, motherwort, saw palmetto, fenugreek, black cohosh, kelp, and ginger. The listing describes it as a daily women''s multivitamin with botanicals "traditionally included in women''s wellness routines" and makes no specific health claims. The vitamin doses are low for a multivitamin, and the amount of each herb isn''t disclosed. 2 gummies a day; 60 gummies (30 servings) per bottle.', '$17.99 for 60 gummies on Amazon; $29.99 on the brand''s site (sold out)', 'https://m.media-amazon.com/images/I/51slr4TLhVL._AC_SL500_.jpg', 'https://curvybodybears.com/products/cbb-gummies-womens-support-supplement-berry-flavored-60-gummies-1-month-supply', '["cbb","curvy body bears","multivitamin","gummies","herbal","black cohosh","maca","ginseng","vegan","supplement"]'::jsonb, '["supplement"]'::jsonb, '["curvybodybears.com","Amazon"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"A dietary supplement, which the FDA does not evaluate for safety or efficacy. The label says its statements have not been evaluated by the FDA and that it is not intended to diagnose, treat, cure, or prevent any disease.","materials":"Pectin gummies (vegan, gluten-free, soy-free, non-GMO per the listing), berry flavored, colored with Blue 1. Each 2-gummy serving has 3 g of sugar. Made in China for C.B.B. LLC.","recalls":"No recalls found.","sideEffects":"The label''s only direction is to take two gummies a day and not exceed that dose; no warnings were shown. It contains black cohosh, which has been linked to rare liver injury; the US Pharmacopeia recommends a warning for people with liver disorders, and pregnant women are advised not to take it without supervision (NIH). It also contains kelp, a source of iodine, but the label doesn''t say how much. Full warnings are listed below.","opinionAlerts":"Herb amounts are hidden in a 450 mg blend split across nine herbs, so it''s not possible to know whether any is present at a studied dose. Contains black cohosh (rare liver injury reports) and kelp (iodine, amount not listed). The Amazon ingredient text and the bottle''s Supplement Facts don''t fully match. No study of this product was found."}'::jsonb, 'CBB describes these as daily women''s multivitamin gummies that pair vitamins A, C, E, and B6 with nine botanicals "traditionally included in women''s wellness routines." The listing doesn''t claim any specific health benefit. No study of this product was found.

The vitamin amounts are modest: 100% of the daily value for vitamin E, 59% for B6, 28% for C, and 4% for A, with no minerals. As a multivitamin it covers less than most.

The nine herbs share a single 450 mg blend, an average of 50 mg each, and the label doesn''t say how much of any one is in it. That makes it impossible to compare with studies of those herbs.

Two of the herbs carry safety notes from NIH''s Office of Dietary Supplements (ODS). Black cohosh, usually taken for menopause symptoms, has been linked to at least 83 reports of liver damage worldwide. ODS says a causal link hasn''t been shown, but the US Pharmacopeia recommends a warning for people with liver disorders, and pregnant women are advised not to take it unless a provider supervises. ODS also notes that trials, including a 2016 meta-analysis of 4 trials in 511 women, found it didn''t reliably reduce hot flashes. Kelp is a source of iodine. ODS says too much iodine can cause thyroid problems, and kelp is usually avoided on low-iodine diets such as before radioactive iodine treatment. The label doesn''t list the iodine content.', 'On Amazon it has 4.4 out of 5 stars from 1,300 ratings as of October 2026: 78% five stars, 4% four, 6% three, 5% two, and 7% one star. The brand''s own product page shows no reviews and lists the product as sold out.', 'Low-dose vitamins with nine herbs in an undisclosed blend. No study of this product was found, and the herb amounts can''t be compared with research.', 'brand', 'Product description is sourced from CBB''s Amazon listing; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"curvybodybears.com":"https://curvybodybears.com/products/cbb-gummies-womens-support-supplement-berry-flavored-60-gummies-1-month-supply","Amazon":"https://www.amazon.com/dp/B0BWSMCMTZ"},"ingredients":"Supplement Facts per the bottle shown on Amazon. Serving size 2 gummies (5 g); 30 servings per container. Calories 15; total carbohydrates 4 g (1% DV); sugars 3 g. Vitamin A (as retinol acetate) 35 mcg RAE (4% DV). Vitamin C (as ascorbic acid) 25 mg (28% DV). Vitamin E (as alpha tocopherol acetate) 15 mg (100% DV). Vitamin B6 (as pyridoxine HCl) 1 mg (59% DV). Proprietary herbal blend 450 mg: maca root, Panax ginseng root, star anise fruit, motherwort herb, saw palmetto fruit, fenugreek seed, black cohosh root, kelp, ginger root; amounts of each not disclosed. Other ingredients: glucose syrup, white granulated sugar, isomalt, pectin, DL-malic acid, trisodium citrate, natural flavor, color (Blue 1). Distributed by C.B.B. LLC, Hoboken, NJ; country of origin China. The Amazon ingredient text lists slightly different forms (vitamin A as retinyl palmitate, vitamin E as d-alpha tocopheryl succinate, anise seed instead of star anise) and omits Blue 1.","doctorOpinionShort":"Low-dose vitamins A, C, E, and B6 plus nine herbs in an undisclosed 450 mg blend, with no specific health claims. Contains black cohosh, linked to rare liver injury and not advised in pregnancy without supervision, and kelp, an unmeasured iodine source. No study of this product was found.","doctorOpinionCitations":[{"url":"https://www.amazon.com/dp/B0BWSMCMTZ","label":"Amazon: CBB 13 in 1 Women''s Gummies listing and Supplement Facts"},{"url":"https://ods.od.nih.gov/factsheets/BlackCohosh-HealthProfessional/","label":"NIH Office of Dietary Supplements: Black cohosh fact sheet","chipLabel":"NIH ODS: black cohosh"},{"url":"https://ods.od.nih.gov/factsheets/Iodine-Consumer/","label":"NIH Office of Dietary Supplements: Iodine fact sheet for consumers","chipLabel":"NIH ODS: iodine"}],"whoItsFor":["Adults who want a low-dose vitamin gummy and are comfortable with an undisclosed herbal blend","Not for pregnancy (unless a provider supervises), liver problems, or thyroid conditions without a doctor''s OK (black cohosh and kelp)","Not a substitute for a full multivitamin if you need minerals such as iron, calcium, or vitamin D"],"howToUse":{"intro":"Per the label shown on Amazon: adults take two gummies a day.","steps":["Chew 2 gummies thoroughly before swallowing.","Don''t take more than the recommended dose."],"sourceUrl":"https://www.amazon.com/dp/B0BWSMCMTZ","sourceLabel":"Amazon: CBB 13 in 1 Women''s Gummies"},"warnings":["Liver disorders, or symptoms like abdominal pain, dark urine, or yellowing skin: avoid or stop and see a doctor. Contains black cohosh (US Pharmacopeia recommendation, via NIH ODS).","Pregnant: don''t take black cohosh unless a provider supervises (American Herbal Products Association, via NIH ODS).","Thyroid conditions, a low-iodine diet, or thyroid medication: contains kelp, an iodine source, in an unlisted amount (NIH ODS).","Contains 3 g of sugar per serving and Blue 1 dye."],"ingredientScience":[{"name":"Black cohosh","text":"Usually taken for menopause symptoms. NIH ODS reports at least 83 cases of liver damage worldwide, though a causal link hasn''t been shown; the US Pharmacopeia recommends a caution for people with liver disorders. For hot flashes, a 2012 Cochrane review of 16 trials (2,027 women) found insufficient evidence for or against it, and a 2016 meta-analysis of 4 trials (511 women) found no significant reduction. This product doesn''t disclose how much it contains.","citations":[{"url":"https://ods.od.nih.gov/factsheets/BlackCohosh-HealthProfessional/","label":"NIH Office of Dietary Supplements: Black cohosh fact sheet for health professionals"}]},{"name":"Kelp (iodine source)","text":"Kelp supplements contain iodine. NIH ODS sets the adult upper limit at 1,100 mcg of iodine a day from all sources and says too much can cause goiter, thyroid inflammation, and other thyroid problems. High-dose iodine can interact with antithyroid drugs such as methimazole. The label doesn''t list the kelp or iodine amount.","citations":[{"url":"https://ods.od.nih.gov/factsheets/Iodine-Consumer/","label":"NIH Office of Dietary Supplements: Iodine fact sheet for consumers"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"amazon","url":"https://www.amazon.com/dp/B0BWSMCMTZ","text":"Amazon: CBB 13 in 1 Women''s Gummies reviews","summary":"4.4 out of 5 stars from 1,300 ratings on Amazon as of October 2026."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
